#!/usr/bin/env python3
"""
fx.py - 47 video effects in one script: edit-style presets (zooms, glitches, transitions) and short "scene" effects
(magazine cover, chat window, phone mock-up, growth chart ...). Works with any resolution / fps / orientation; audio is kept.

Usage:
  python fx.py --check                                    # are Python packages, ffmpeg and bundled models in place?
  python fx.py --list                                     # all effects: number | id | Russian name | description
  python fx.py INPUT.mp4 OUTPUT.mp4 --effect sparkle      # by id, English alias, Russian name or number (--effect 38)
  python fx.py INPUT.mp4 OUTPUT.mp4 --effect magazine --start 0.3 --duration 3 --text "MY MAGAZINE"
  python fx.py INPUT.mp4 OUTPUT_DIR --effect all          # every effect, one file each

Needs: python 3.9+, numpy, opencv-python (or opencv-python-headless), pillow, ffmpeg + ffprobe in PATH. All timings are in seconds.
Author: NeuroLena. MIT licence (see LICENSE and THIRD_PARTY_NOTICES.md).
"""
import argparse, json, os, subprocess, sys, shutil
import numpy as np
import cv2
try:
    from i18n import DESC_EN
except ImportError:
    DESC_EN = {}

# ----------------------------------------------------------------------------- helpers
def ease(x):
    x = np.clip(x, 0.0, 1.0)
    return x * x * (3 - 2 * x)

def kf(t, pts):
    """piece-wise linear keyframes [(t, v), ...]"""
    return float(np.interp(t, [p[0] for p in pts], [p[1] for p in pts]))

def tri(x):
    """triangle wave 0..1..0 with period 1"""
    x = x % 1.0
    return 1 - abs(2 * x - 1)

def warp(img, s=1.0, tx=0.0, ty=0.0, rot=0.0, cx=None, cy=None, border=cv2.BORDER_REFLECT101, bval=0):
    H, W = img.shape[:2]
    cx = W / 2 if cx is None else cx
    cy = H / 2 if cy is None else cy
    M = cv2.getRotationMatrix2D((cx, cy), rot, s)
    M[0, 2] += tx
    M[1, 2] += ty
    return cv2.warpAffine(img, M, (W, H), flags=cv2.INTER_LINEAR, borderMode=border, borderValue=bval)

def gray3(img):
    g = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY)
    return cv2.merge([g, g, g])

def mix(a, b, w):
    """a*(1-w)+b*w, w scalar or HxW array"""
    if np.isscalar(w):
        if w <= 0: return a
        if w >= 1: return b
        return cv2.addWeighted(a, 1 - w, b, w, 0)
    w3 = w[..., None] if w.ndim == 2 else w
    return (a.astype(np.float32) * (1 - w3) + b.astype(np.float32) * w3).clip(0, 255).astype(np.uint8)

def flash(img, a, color=(255, 255, 255)):
    if a <= 0: return img
    over = np.empty_like(img); over[:] = color
    return mix(img, over, min(1.0, a))

def add_bright(img, v):
    return np.clip(img.astype(np.float32) + v, 0, 255).astype(np.uint8)

def shift_plane(p, dx, dy):
    return np.roll(np.roll(p, int(dy), axis=0), int(dx), axis=1)

def resize(img, w, h):
    w, h = max(1, int(round(w))), max(1, int(round(h)))
    interp = cv2.INTER_AREA if (w < img.shape[1] or h < img.shape[0]) else cv2.INTER_LINEAR
    return cv2.resize(img, (w, h), interpolation=interp)

def place_card(canvas, card, cx, cy, rot=0.0, alpha=1.0, border_px=0, border_col=(245, 245, 245)):
    """alpha-composite a (rotated) card centred on (cx, cy)."""
    H, W = canvas.shape[:2]
    card = card.copy()
    h, w = card.shape[:2]
    if border_px > 0:
        cv2.rectangle(card, (0, 0), (w - 1, h - 1), border_col, border_px)
    M = cv2.getRotationMatrix2D((w / 2, h / 2), rot, 1.0)
    M[0, 2] += cx - w / 2
    M[1, 2] += cy - h / 2
    wc = cv2.warpAffine(card, M, (W, H), flags=cv2.INTER_LINEAR, borderMode=cv2.BORDER_CONSTANT)
    m = cv2.warpAffine(np.full((h, w), 255, np.uint8), M, (W, H), flags=cv2.INTER_LINEAR,
                       borderMode=cv2.BORDER_CONSTANT).astype(np.float32) / 255.0 * alpha
    if m.max() <= 0: return canvas
    return mix(canvas, wc, m)

def box_blur_h(img, k):
    k = max(1, int(k))
    return cv2.blur(img, (k | 1, 1)) if k > 1 else img

class Ctx:
    def __init__(self, W, H, fps, seed):
        self.W, self.H, self.fps, self.seed = W, H, fps, seed
        self.sc = W / 1080.0          # all pixel constants below are authored for 1080 px width
        self.i = 0                    # frame index
        self.state = {}
        self.fixed_face = None        # (x, y, w, h) as fractions of the frame, for "mosaic"
        self.buf = {}                 # frame cache around the current frame (for effects that look at other moments)
        self.n_read = 0
        self.no_matte = False
        self.opts = {}
        self.thumbs = {}              # small copies of frames around the current one (effects that show other moments)
    def neighbor(self, dt):
        """frame at (current time + dt seconds); falls back to the nearest frame that is available"""
        j = self.i_abs + int(round(dt * self.fps))
        lo = min(self.buf) if self.buf else 0
        j = max(lo, min(self.n_read - 1, j))
        return self.buf[j]
    def thumb(self, dt):
        j = self.i_abs + int(round(dt * self.fps))
        lo = min(self.thumbs) if self.thumbs else 0
        j = max(lo, min(max(self.thumbs), j))
        return self.thumbs[j]
    def rng(self, *k):
        return np.random.default_rng([self.seed, *[int(x) & 0x7fffffff for x in k]])

# ----------------------------------------------------------------------------- 1. блеск
def fx_sparkle(img, t, c):
    W, H, sc = c.W, c.H, c.sc
    layer = np.zeros((H, W), np.float32)
    N = 62
    for i in range(N):
        r = c.rng(1, i)
        period = r.uniform(0.28, 0.9)
        off = r.uniform(0, period)
        n = int(np.floor((t + off) / period)); u = (t + off) / period - n
        rr = c.rng(2, i, n)
        x, y = rr.uniform(0, W), rr.uniform(0, H)
        size = float(np.exp(rr.uniform(np.log(0.7), np.log(3.6)))) * sc
        big = rr.random() < 0.30
        ray = size * (rr.uniform(9, 18) if big else rr.uniform(2.5, 5.5))
        env = float(np.sin(np.pi * u) ** 1.2)
        if env < 0.03: continue
        R = int(ray * 3 + 3)
        x0, x1 = int(max(0, x - R)), int(min(W, x + R + 1))
        y0, y1 = int(max(0, y - R)), int(min(H, y + R + 1))
        if x1 <= x0 or y1 <= y0: continue
        xs = np.arange(x0, x1, dtype=np.float32)[None, :] - x
        ys = np.arange(y0, y1, dtype=np.float32)[:, None] - y
        core = np.exp(-(xs ** 2 + ys ** 2) / (2 * (size * 0.55) ** 2))
        hray = np.exp(-np.abs(xs) / (ray * 0.55)) * np.exp(-(ys ** 2) / (2 * (0.55 * sc) ** 2))
        vray = np.exp(-np.abs(ys) / (ray * 0.55)) * np.exp(-(xs ** 2) / (2 * (0.55 * sc) ** 2))
        star = np.clip(core * 1.4 + 0.9 * np.maximum(hray, vray), 0, 1) * env
        layer[y0:y1, x0:x1] = np.maximum(layer[y0:y1, x0:x1], star)
    out = img.astype(np.float32) + layer[..., None] * 255.0
    return np.clip(out, 0, 255).astype(np.uint8)

# ----------------------------------------------------------------------------- 2. вертикальный сбой
def _shift_rep(p, dx, dy):
    M = np.float32([[1, 0, dx], [0, 1, dy]])
    return cv2.warpAffine(p, M, (p.shape[1], p.shape[0]), flags=cv2.INTER_LINEAR, borderMode=cv2.BORDER_REPLICATE)

def fx_vglitch(img, t, c):
    W, H, sc = c.W, c.H, c.sc
    rng = c.rng(3, c.i // 2)
    # The reference's R/G/B planes drift apart: G follows the measured camera path (tx -37..0 px), B moves the opposite way,
    # R jumps vertically from time to time.
    M = motion_matrix("vglitch", t, W, H)
    b, g, r = cv2.split(img)
    g = cv2.warpAffine(g, M, (W, H), flags=cv2.INTER_LINEAR, borderMode=cv2.BORDER_REPLICATE)
    b = _shift_rep(b, -M[0, 2], 0)
    dy = rng.uniform(0, 45) * sc if rng.random() < 0.6 else 0
    r = _shift_rep(r, 0, dy)
    out = cv2.merge([b, g, r]).astype(np.float32)
    out = out * 1.1 + 8
    # vertical smear + per-column vertical jitter (streaks), no wrap-around
    out = cv2.blur(out, (1, max(1, int(9 * sc)) | 1))
    bw = max(3, int(7 * sc))
    cols = np.repeat(rng.normal(0, 5 * sc, (W + bw - 1) // bw), bw)[:W].astype(np.float32)
    yy, xx = np.mgrid[0:H, 0:W].astype(np.float32)
    out = cv2.remap(out, xx, yy - cols[None, :], cv2.INTER_LINEAR, borderMode=cv2.BORDER_REPLICATE)
    # dark vertical lines, period ~21.5 px @1080
    xs = np.arange(W, dtype=np.float32)
    ph = (xs / (21.5 * sc)) % 1.0
    line = 1 - 0.30 * np.clip(1 - np.abs(ph - 0.12) / 0.11, 0, 1)
    out *= line[None, :, None]
    # chroma / luma grain
    n = rng.normal(0, 9, (max(1, H // 3), max(1, W // 3), 3)).astype(np.float32)
    out += cv2.resize(n, (W, H), interpolation=cv2.INTER_NEAREST)
    return np.clip(out, 0, 255).astype(np.uint8)

# ----------------------------------------------------------------------------- 3. выпадение
_DROP = [(0, .80), (1, .804), (2, .807), (3, .811), (4, .819), (5, .822), (6, .831), (7, .841), (8, .852),
         (9, .865), (10, .88), (11, .896), (12, .915), (13, .933), (14, .95), (15, .963), (16, .97),
         (17, .979), (18, .985), (19, .99), (20, .996), (22, 1.0)]
def fx_dropin(img, t, c):
    s = kf(t * 30, _DROP)
    if s >= 0.9995: return img
    H, W = img.shape[:2]
    small = resize(img, W * s, H * s)
    out = np.zeros_like(img)
    y0 = (H - small.shape[0]) // 2; x0 = (W - small.shape[1]) // 2
    out[y0:y0 + small.shape[0], x0:x0 + small.shape[1]] = small
    return out

# ----------------------------------------------------------------------------- 4. детали
_CARDS = [  # (appear frame@30, cx, cy, width, rotation deg(ccw+))  relative to W,H
    (19, .278, .700, .345, -6.0),   # bottom-left
    (25, .239, .281, .348, 2.0),    # top-left
    (31, .678, .251, .354, -1.2),   # top-right
    (37, .726, .703, .357, 1.0),    # bottom-right
    (41, .500, .501, .343, 0.0),    # centre (on top)
]
def fx_details(img, t, c):
    W, H, sc = c.W, c.H, c.sc
    f = t * 30.0
    if f > 95: return img
    out = img
    # first small flash
    if 7 <= f <= 13:
        out = flash(out, 0.55 * max(0.0, 1 - abs(f - 9.5) / 3.0), (240, 248, 252))
    if 12 <= f < 82:
        sig = kf(f, [(12, 0.1), (16, 21 * sc)])
        if sig > 0.5:
            bg = cv2.GaussianBlur(img, (0, 0), sig)
            out = mix(out, bg, ease((f - 12) / 3.5)) if f < 16 else bg
        for (fa, cx, cy, w, rot) in _CARDS:
            if f < fa: continue
            u = (f - fa) / 4.0
            card = resize(img, W * w, H * w)
            card = flash(card, max(0.0, 1 - u))
            out = place_card(out, card, cx * W, cy * H, rot, 1.0, max(1, int(3 * sc)), (238, 238, 238))
    if 82 <= f <= 94:
        k = ease((f - 84) / 9.0)
        z = 1.12 - 0.12 * k
        out = warp(img, s=z)
        out = flash(out, 0.9 * (1 - k), (250, 250, 250))
    return out

# ----------------------------------------------------------------------------- 5. застёжка
def fx_clasp(img, t, c):
    W, H, sc = c.W, c.H, c.sc
    f = t * 30.0
    if f > 70: return img
    if f < 8: return np.zeros_like(img)
    G = gray3(img)
    edge = int(kf(f, [(8, 0.0), (14, 0.25), (20, 0.55), (28, 0.80), (38, 0.86)]) * W)
    base = np.zeros_like(img)
    base[:, :edge] = G[:, :edge]
    if f < 36:                                   # detached sliver ahead of the "zip"
        sx0 = min(W, edge + int(0.09 * W)); sx1 = min(W, sx0 + int(0.07 * W))
        base[:, sx0:sx1] = G[:, sx0:sx1]
    if f < 38:
        return base
    zoomed = warp(img, s=1.5, ty=-0.10 * H)
    out = base
    if f < 46:                                   # diagonal wipe, colour + zoomed behind the edge
        p = ease((f - 37) / 8.0)
        xb = W * (1.25 - 1.55 * p)
        yy, xx = np.mgrid[0:H, 0:W].astype(np.float32)
        bound = xb - 0.35 * W / H * (yy - H / 2)
        mask = cv2.GaussianBlur((xx > bound).astype(np.float32), (0, 0), 1.2)
        out = mix(base, zoomed, mask)
        dist = np.abs(xx - bound)
        sh = np.clip(1 - dist / (14 * sc), 0, 1) * 0.35 * (xx <= bound)
        out = (out.astype(np.float32) * (1 - sh[..., None])).astype(np.uint8)
    else:
        q = ease((f - 45) / 2.5)
        out = mix(zoomed, img, q)
        if f > 49:                               # double exposure with the zoomed copy
            za = 0.8 * np.sin(np.pi * np.clip((f - 49) / 6.0, 0, 1))
            out = mix(out, zoomed, za)
    fa = 0.9 * np.exp(-((f - 56.5) / 3.0) ** 2)
    if f > 58: fa = max(fa, 0.5 * max(0.0, 1 - (f - 58) / 12.0))
    return flash(out, fa, (250, 250, 250))

