def motion_matrix(name, t, W, H):
    tb = _MOTION[name]; rows = tb["m"]; step = tb["step"]
    dur = (len(rows) - 1) * step / tb["fps"]
    u = t % (2 * dur)
    if u > dur: u = 2 * dur - u                       # ping-pong beyond the measured length
    pos = u * tb["fps"] / step; i = min(int(pos), len(rows) - 1); fr = pos - i
    a = rows[i]; b = rows[min(i + 1, len(rows) - 1)]
    m = [a[j] + (b[j] - a[j]) * fr for j in range(6)]
    # measured on a 270x480 frame; re-express in normalised coordinates so any aspect ratio works
    return np.float32([[m[0], m[1] * (480 / 270.0) * (W / H), m[2] * W / 270.0],
                       [m[3] * (270 / 480.0) * (H / W), m[4], m[5] * H / 480.0]])

def cam(img, name, t, c):
    return cv2.warpAffine(img, motion_matrix(name, t, c.W, c.H), (c.W, c.H), flags=cv2.INTER_LINEAR, borderMode=cv2.BORDER_REFLECT101)

def fx_pulse(img, t, c):
    M = motion_matrix("pulse", t, c.W, c.H)
    return cv2.warpAffine(img, M, (c.W, c.H), flags=cv2.INTER_LINEAR, borderMode=cv2.BORDER_REFLECT101)

# ----------------------------------------------------------------------------- 7. мозаика
_face_det = {}
def _asset(name):
    here = os.path.dirname(os.path.abspath(__file__))
    for p in (os.path.join(here, "..", "assets", name), os.path.join(here, "assets", name), os.path.join(here, name)):
        if os.path.exists(p): return p
    return None

def detect_face(img):
    """largest frontal face as a Haar-style square box (x, y, w, h) in pixels, or None.
    Tries YuNet (cv2.FaceDetectorYN + assets/face_detection_yunet_2023mar.onnx), then the Haar cascade."""
    H, W = img.shape[:2]
    s = 640.0 / W
    small = cv2.resize(img, (640, max(1, int(H * s))))
    d = _face_det
    if "yunet" not in d:
        d["yunet"] = None
        mp = _asset("face_detection_yunet_2023mar.onnx")
        if mp and hasattr(cv2, "FaceDetectorYN"):
            try: d["yunet"] = cv2.FaceDetectorYN.create(mp, "", (640, 640), 0.6, 0.3, 5000)
            except Exception: d["yunet"] = None
    if d["yunet"] is not None:
        try:
            d["yunet"].setInputSize((small.shape[1], small.shape[0]))
            _, faces = d["yunet"].detect(small)
            if faces is not None and len(faces):
                x, y, w, h = max(faces, key=lambda r: r[2] * r[3])[:4]
                wh = 1.04 * w                                  # convert YuNet's tall box to the square Haar-style box
                return np.array([(x + w / 2 - 0.008 * w - wh / 2) / s, (y + h / 2 - 0.036 * w - wh / 2) / s, wh / s, wh / s], np.float32)
        except Exception:
            pass
    if "haar" not in d:
        d["haar"] = None
        if hasattr(cv2, "CascadeClassifier"):
            cands = [_asset("haarcascade_frontalface_default.xml")]
            if hasattr(cv2, "data"): cands.append(os.path.join(cv2.data.haarcascades, "haarcascade_frontalface_default.xml"))
            h_ = cv2.CascadeClassifier()
            for p_ in cands:
                if p_ and os.path.exists(p_) and h_.load(p_):
                    d["haar"] = h_; break
    if d["haar"] is not None:
        g = cv2.cvtColor(small, cv2.COLOR_BGR2GRAY)
        faces = d["haar"].detectMultiScale(g, 1.1, 5, minSize=(40, 40))
        if len(faces):
            x, y, w, h = max(faces, key=lambda r: r[2] * r[3])
            return np.array([x / s, y / s, w / s, h / s], np.float32)
    return None

def fx_mosaic(img, t, c):
    W, H = c.W, c.H
    img = cam(img, "mosaic", t, c)
    st = c.state
    if c.fixed_face is not None and "box" not in st:
        fx_, fy_, fw_, fh_ = c.fixed_face
        st["box"] = np.array([fx_ * W, fy_ * H, fw_ * W, fh_ * H], np.float32)
        st["locked"] = True
    if not st.get("locked") and (c.i % 3 == 0 or "box" not in st):
        b = detect_face(img)
        if b is not None:
            st["box"] = b if "box" not in st else 0.6 * st["box"] + 0.4 * b
        elif "box" not in st:
            st["box"] = np.array([W * .327, H * .255, W * .352, H * .198], np.float32)   # default portrait framing
    x, y, w, h = st["box"]
    # calibrated on the reference: an oval over the face (hairline-to-chin), made of 26-px blocks (at 1080 px width)
    ecx, ecy = x + w * 0.5 + 0.005 * w, y + h * 0.5 + 0.005 * h
    ea, eb = 0.62 * w, 0.63 * h
    blk = max(4, int(round(0.02444 * W)))
    x0 = int(max(0, ecx - ea)) // blk * blk; x1 = min(W + blk, (int(ecx + ea) // blk + 1) * blk)
    y0 = int(max(0, ecy - eb)) // blk * blk; y1 = min(H + blk, (int(ecy + eb) // blk + 1) * blk)
    pad = cv2.copyMakeBorder(img, 0, max(0, y1 - H), 0, max(0, x1 - W), cv2.BORDER_REPLICATE)
    reg = pad[y0:y1, x0:x1]
    small = cv2.resize(reg, ((x1 - x0) // blk, (y1 - y0) // blk), interpolation=cv2.INTER_AREA)
    gy, gx = np.mgrid[0:small.shape[0], 0:small.shape[1]]
    bcx = x0 + (gx + 0.5) * blk; bcy = y0 + (gy + 0.5) * blk
    inside = (((bcx - ecx) / ea) ** 2 + ((bcy - ecy) / eb) ** 2) <= 1.0
    big = cv2.resize(small, (x1 - x0, y1 - y0), interpolation=cv2.INTER_NEAREST)
    m = cv2.resize(inside.astype(np.uint8), (x1 - x0, y1 - y0), interpolation=cv2.INTER_NEAREST).astype(bool)
    out = pad.copy()
    sub = out[y0:y1, x0:x1]
    sub[m] = big[m]
    return out[:H, :W]

# ----------------------------------------------------------------------------- 8. мягкий
def fx_soft(img, t, c):
    W, H, sc = c.W, c.H, c.sc
    out = cv2.warpAffine(img, motion_matrix("soft", t, W, H), (W, H), flags=cv2.INTER_LINEAR, borderMode=cv2.BORDER_REFLECT101)
    soft = cv2.GaussianBlur(out, (0, 0), 1.3 * sc)
    glow = cv2.GaussianBlur(out, (0, 0), 14 * sc)
    return cv2.addWeighted(soft, 0.88, glow, 0.12, 0)

# ----------------------------------------------------------------------------- 9. нарезка и слияние  (loops every 3 s)
_SM_BANDS = [  # y0, y1, zoom, srcCx, srcCy   (fractions)
    (0.0, .1875, 1.40, .358, .187),
    (.1875, .50, 1.35, .630, .384),
    (.50, .8125, 1.50, .333, .602),
    (.8125, 1.0, 1.65, .697, .792),
]
_WARM = np.array([[0.935, 0.080, -0.052, 6.5], [0.005, 0.979, -0.020, -0.7], [-0.052, 0.051, 0.878, 5.0]], np.float32)  # rows out R,G,B ; cols in R,G,B,bias
def grade(img, M):
    f = img.astype(np.float32)
    B, G, R = f[..., 0], f[..., 1], f[..., 2]
    oR = M[0, 0] * R + M[0, 1] * G + M[0, 2] * B + M[0, 3]
    oG = M[1, 0] * R + M[1, 1] * G + M[1, 2] * B + M[1, 3]
    oB = M[2, 0] * R + M[2, 1] * G + M[2, 2] * B + M[2, 3]
    return np.clip(cv2.merge([oB, oG, oR]), 0, 255).astype(np.uint8)

def fx_slicemerge(img, t, c):
    W, H = c.W, c.H
    f = (t % 3.0) * 30.0
    base = grade(img, _WARM)
    e = kf(f, [(0, 0), (9, 0), (10, 0), (24, 1), (50, 1), (54, .6), (58, 0)])
    out = base
    if e > 0.001:
        out = base.copy()
        for bi, (a, b, z, cx, cy) in enumerate(_SM_BANDS):
            yc = (a + b) / 2
            zz = 1 + (z - 1) * ease(e); ccx = 0.5 + (cx - 0.5) * ease(e); ccy = yc + (cy - yc) * ease(e)
            M = np.float32([[zz, 0, 0.5 * W - zz * ccx * W], [0, zz, yc * H - zz * ccy * H]])
            w = cv2.warpAffine(base, M, (W, H), flags=cv2.INTER_LINEAR, borderMode=cv2.BORDER_REFLECT101)
            y0, y1 = int(a * H), int(b * H)
            band = w[y0:y1]
            # random white wash of a band, 2 frames
            rr = c.rng(9, bi, int(t // 3.0))
            fl = rr.uniform(26, 52)
            if fl <= f < fl + 2.2 and rr.random() < 0.7:
                band = flash(band, 0.75, (238, 248, 255))
            out[y0:y1] = band
    # cream flash at the start of every cycle and a soft one near the end
    out = flash(out, kf(f, [(4, 0), (9, 0.97), (11, 0.97), (13, 0)]), (235, 246, 253))
    out = flash(out, kf(f, [(53, 0), (55, 1.0), (57, 1.0), (59.5, 0)]), (235, 246, 253))
    out = flash(out, kf(f, [(62, 0), (64.5, 0.35), (68, 0)]), (235, 246, 253))
    return out

# ----------------------------------------------------------------------------- 10. полоса
def _reflect(canvas, card, cx, cy, strength=0.30):
    H, W = canvas.shape[:2]
    ch, cw = card.shape[:2]
    y0 = int(cy + ch / 2); rh = int(min(ch * 0.45, H - y0))
    if rh <= 4: return
    refl = cv2.flip(card, 0)[:rh]
    fade = np.linspace(strength, 0.0, rh, dtype=np.float32)[:, None, None]
    x0 = int(cx - cw / 2); x1 = x0 + cw
    cx0, cx1 = max(0, x0), min(W, x1)
    if cx1 <= cx0: return
    r = (refl[:, cx0 - x0: cx1 - x0].astype(np.float32) * fade).astype(np.uint8)
    canvas[y0:y0 + rh, cx0:cx1] = np.maximum(canvas[y0:y0 + rh, cx0:cx1], r)

def fx_strip(img, t, c):
    W, H, sc = c.W, c.H, c.sc
    f = t * 30.0
    if f >= 114: return img
    canvas = np.zeros_like(img)
    cy = H / 2
    dim = lambda im, k: cv2.GaussianBlur((im.astype(np.float32) * k).astype(np.uint8), (0, 0), 1.5 * sc)
    # phase 1: card shrinks to ~0.8 and the strip scrolls out to the left
    if f < 46:
        s1 = kf(f, [(0, 1.0), (6, .94), (12, .81), (36, .80), (46, .78)])
        cx1 = kf(f, [(0, .5), (12, .5), (18, .48), (24, .385), (30, .244), (36, .04), (46, -.2)]) * W
        card = resize(img, W * s1, H * s1); cw = card.shape[1]; pitch = cw * 1.03
        mv = abs(kf(f + 1, [(0, .5), (12, .5), (18, .48), (24, .385), (30, .244), (36, .04), (46, -.2)]) - kf(f - 1, [(0, .5), (12, .5), (18, .48), (24, .385), (30, .244), (36, .04), (46, -.2)])) * W
        for k in (2, 1):
            d = dim(card, 0.42 if k == 1 else 0.28)
            canvas = place_card(canvas, d, cx1 + k * pitch, cy)
            _reflect(canvas, d, cx1 + k * pitch, cy, 0.18)
        if mv > 25 * sc: card = box_blur_h(card, int(min(mv * 0.5, 80 * sc)))
        canvas = place_card(canvas, card, cx1, cy)
        _reflect(canvas, card, cx1, cy, 0.30)
    # phase 2: tiny strip
    a2 = kf(f, [(40, 0), (44, 1), (80, 1), (98, 0)])
    if a2 > 0.01:
        s2 = kf(f, [(40, .78), (48, .30), (200, .30)])
        card = resize(img, W * s2, H * s2); cw = card.shape[1]; ch = card.shape[0]; pitch = cw * 1.08
        cxm = (0.54 if f < 60 else 0.5) * W
        tiny = np.zeros_like(img)
        for k in (-3, -2, -1, 1, 2, 3):
            d = dim(card, 0.42 if abs(k) == 1 else 0.28)
            tiny = place_card(tiny, d, cxm + k * pitch, cy)
            _reflect(tiny, d, cxm + k * pitch, cy, 0.18)
        if f < 58:
            tiny = place_card(tiny, card, cxm, cy); _reflect(tiny, card, cxm, cy, 0.30)
        canvas = np.maximum(canvas, (tiny.astype(np.float32) * a2).astype(np.uint8))
        if 44 <= f <= 72:
            gy = int(cy + ch / 2 + 2); gx0 = int(cxm - cw * 0.55); gx1 = int(cxm - cw * 0.05)
            canvas[gy:gy + max(1, int(3 * sc)), max(0, gx0):max(0, gx1)] = (235, 235, 235)
    # phase 3: bright blurred card flies in from the right and grows to full frame
    if f >= 56:
        s3 = kf(f, [(56, .70), (66, .70), (72, .72), (78, .74), (84, .75), (90, .79), (96, .85), (102, .91), (108, .97), (114, 1.0)])
        cx3 = kf(f, [(56, 1.40), (66, 1.12), (72, .98), (78, .78), (84, .64), (90, .55), (96, .52), (102, .51), (108, .5), (114, .5)]) * W
        bl = kf(f, [(56, 70), (72, 55), (84, 30), (96, 10), (104, 0)]) * sc
        card = resize(img, W * s3, H * s3)
        if bl > 2: card = box_blur_h(card, int(bl))
        canvas = place_card(canvas, card, cx3, cy)
        _reflect(canvas, card, cx3, cy, 0.25)
    return canvas

# ----------------------------------------------------------------------------- 11. проклятое видение
# tone curve measured on the reference (luma -> R, G, B), plus a strong vignette
_CUR_LUT = np.array([[8.0, 30.0, 39.0, 23.0], [24.0, 40.0, 50.0, 33.0], [40.0, 51.0, 64.0, 42.0], [56.0, 66.0, 81.0, 55.0], [72.0, 81.0, 98.0, 67.0], [88.0, 98.0, 116.0, 81.0], [104.0, 110.0, 134.0, 92.0], [120.0, 124.0, 155.0, 111.0], [136.0, 133.0, 176.0, 125.0], [152.0, 140.0, 199.0, 142.0], [168.0, 152.0, 222.0, 161.0], [184.0, 156.0, 236.0, 178.0], [200.0, 170.0, 250.0, 200.0], [216.0, 172.0, 250.0, 205.0]], np.float32)
_CUR_VIG = ([0, 0.2, 0.55, 0.8, 1.1, 1.6], [1, 1, 0.94, 0.84, 0.74, 0.62])
_CUR_GHOST = [(0, 10.5), (46, 49), (83, 90), (94, 102)]      # frames@30 where the flipped ghost shows (first 3.4 s, then repeats every 6 s)
def fx_cursed(img, t, c):
    W, H, sc = c.W, c.H, c.sc
    rng = c.rng(11, c.i)
    f = img.astype(np.float32)
    L = 0.299 * f[..., 2] + 0.587 * f[..., 1] + 0.114 * f[..., 0]
    lut = _CUR_LUT
    out = np.stack([np.interp(L, lut[:, 0], lut[:, 3]), np.interp(L, lut[:, 0], lut[:, 2]), np.interp(L, lut[:, 0], lut[:, 1])], axis=-1)
    vig = c.state.get("vig")
    if vig is None:
        yy, xx = np.mgrid[0:H, 0:W].astype(np.float32)
        r = np.hypot((xx - W / 2) / (W / 2), (yy - H / 2) / (H / 2))
        vig = np.interp(r, _CUR_VIG[0], _CUR_VIG[1]).astype(np.float32)[..., None]; c.state["vig"] = vig
    # flipped ghost
    ff = (t % 6.0) * 30.0
    if any(a <= ff < b for a, b in _CUR_GHOST):
        g = cv2.warpAffine(cv2.flip(out, 0), np.float32([[1.05, 0, W / 2 - 1.05 * W / 2], [0, 1.05, H / 2 - 1.05 * H / 2 - 0.05 * H]]), (W, H), borderMode=cv2.BORDER_REFLECT101)
        out = out * 0.68 + g * 0.32
    out = out * vig
    # fine grain (≈3 levels, ~3 px blobs)
    gr = cv2.GaussianBlur(rng.normal(0, 1, (H, W, 1)).astype(np.float32), (0, 0), 1.4 * sc)
    out += (gr[..., None] if gr.ndim == 2 else gr) * 7.5
    # tracking noise: wide speckled bands + short bright pink dashes + a few displaced rows
    for _ in range(int(rng.integers(3, 8))):
        y = int(rng.uniform(0, H)); h = max(2, int(rng.uniform(3, 14) * sc)); y1 = min(H, y + h)
        band = cv2.blur(out[y:y1], (int(rng.uniform(40, 160) * sc) | 1, 1))
        noise = rng.normal(0, 22, (y1 - y, W, 1)).astype(np.float32)
        out[y:y1] = band * 0.65 + 75 + noise
    for _ in range(int(rng.integers(10, 26))):
        y = int(rng.uniform(0, H)); h = max(1, int(rng.uniform(1, 3) * sc)); x0 = int(rng.uniform(0, W)); ln = int(rng.uniform(15, 140) * sc)
        col = np.array([rng.uniform(170, 235), rng.uniform(190, 255), rng.uniform(205, 255)], np.float32)   # B,G,R : pinkish white
        out[y:y + h, x0:x0 + ln] = out[y:y + h, x0:x0 + ln] * 0.3 + col * 0.7
    for _ in range(int(rng.integers(0, 4))):
        y = int(rng.uniform(0, H * .95)); h = max(2, int(rng.uniform(6, 30) * sc)); sh = int(rng.normal(0, 30) * sc)
        out[y:y + h] = np.roll(out[y:y + h], sh, axis=1)
    return np.clip(out, 0, 255).astype(np.uint8)

# ----------------------------------------------------------------------------- 12. разделение на несколько кадров
# The picture is re-tiled into columns whose width shrinks 1 -> 1/2 -> 1/3 -> 1/4 and then grows back to 1.
# Every column is a same-scale crop centred on the face; from f44 the left-most column shows the right edge of the frame.
_SP_W = [(0, 1.0), (22, 1.0), (25, 0.5), (40, 0.5), (50, 1 / 3.0), (58, 1 / 3.0), (66, 0.25), (80, 0.25), (93, 1.0)]
_SP_START = [(0.25, 0.381), (1 / 3.0, 0.36), (0.5, 0.374), (1.0, 0.0)]
def _tiles(img, wt, col0):
    H, W = img.shape[:2]
    if wt >= 0.999: return img
    start = float(np.interp(wt, [p[0] for p in _SP_START], [p[1] for p in _SP_START]))
    cw = max(2, int(round(wt * W))); x0 = int(round(start * W))
    face = img[:, x0:x0 + cw]
    if face.shape[1] < cw: face = np.pad(face, ((0, 0), (0, cw - face.shape[1]), (0, 0)), mode="edge")
    n = -(-W // cw)
    out = np.tile(face, (1, n, 1))[:, :W].copy()
    if col0: out[:, :cw] = img[:, W - cw:]
    return out

def fx_split(img, t, c):
    W, H, sc = c.W, c.H, c.sc
    f = t * 30.0
    if f >= 97: return img
    if f < 5: return np.zeros_like(img)
    if f < 10:
        p = ease((f - 5) / 5.0)
        out = np.zeros_like(img); xo = int(W * (1 - p))
        out[:, xo:] = img[:, :W - xo]
        return out
    wt = kf(f, _SP_W)
    out = _tiles(img, wt, f >= 44)
    cw = int(round(wt * W))
    def bar(o, x0, x1, a, col):
        x0, x1 = int(max(0, x0)), int(min(W, x1))
        if x1 > x0 and a > 0:
            o = o.copy(); o[:, x0:x1] = flash(o[:, x0:x1], a, col)
        return o
    if 78 <= f < 82: out = bar(out, 0, 0.25 * W, 0.97, (0, 0, 0))
    if 82 <= f < 88: out = bar(out, 0.25 * W, 0.5 * W, 0.97 * (1 - ease((f - 85) / 3.0)), (252, 252, 252))
    if 88 <= f < 91: out = bar(out, 0.5 * W, 0.75 * W, 0.30, (60, 60, 60))
    if 91 <= f < 97: out = bar(out, 0.75 * W, W, 0.97 * (1 - ease((f - 93) / 4.0)), (252, 252, 252))
    return out

# ----------------------------------------------------------------------------- 13. сердцебиение встряска
def fx_heartbeat(img, t, c):
    f = (t * 30.0) % 15.0
    if not (2.2 < f < 13.0): return img
    b = np.sin(np.pi * (f - 2.2) / 10.8)
    z = 1 + 0.139 * b
    out = warp(img, s=z, border=cv2.BORDER_REFLECT101)
    return add_bright(out, 46 * min(1.0, b * 1.4))

# ----------------------------------------------------------------------------- 14. смесь
def person_mask(img):
    """rough silhouette: pixels that differ from the background colour sampled along the top edge."""
    H, W = img.shape[:2]
    small = cv2.resize(img, (W // 4, H // 4), interpolation=cv2.INTER_AREA)
    h, w = small.shape[:2]
    patch = np.concatenate([small[:h // 12, :w // 6].reshape(-1, 3), small[:h // 12, -w // 6:].reshape(-1, 3)])
    bg = np.median(patch, axis=0)
    d = np.abs(small.astype(np.float32) - bg).sum(axis=2)
    m = (d > 28).astype(np.uint8) * 255
    m = cv2.morphologyEx(m, cv2.MORPH_CLOSE, np.ones((9, 9), np.uint8))
    n, lab, stats, _ = cv2.connectedComponentsWithStats(m)
    if n > 1:
        k = 1 + np.argmax(stats[1:, 4]); m = (lab == k).astype(np.uint8) * 255
    m = cv2.GaussianBlur(m, (0, 0), 2)
    return cv2.resize(m, (W, H), interpolation=cv2.INTER_LINEAR).astype(np.float32) / 255.0

_MIX_U1 = [(9, 560), (14, 460), (21, 410), (28, 365), (35, 325), (42, 285), (49, 235), (56, 175), (63, 168), (70, 162), (77, 156), (84, 150), (91, 145), (98, 140)]
_MIX_U2 = [(22, -460), (24, -440), (28, -380), (35, -300), (42, -240), (49, -190), (56, -150), (63, -154), (70, -158), (77, -162), (84, -166), (98, -172)]
def fx_mix(img, t, c):
    W, H, sc = c.W, c.H, c.sc
    f = t * 30.0
    if f >= 130: return img
    G = gray3(img)
    out = G.copy()
    k = W / 540.0
    yy, xx = np.mgrid[0:H, 0:W].astype(np.float32)
    u = (xx - 0.463 * yy) / k                              # diagonal coordinate in "540-px" units
    if 9 <= f < 130:
        u1 = kf(f, _MIX_U1); u2 = kf(f, _MIX_U2) if f >= 22 else -9999
        right = warp(img, tx=0.154 * W, ty=-0.164 * H)     # coloured slats are the SAME picture slid along the diagonal
        left = warp(img, tx=-0.157 * W, ty=0.162 * H)
        mr = cv2.GaussianBlur((u > u1).astype(np.float32), (0, 0), 1.0)
        ml = cv2.GaussianBlur((u < u2).astype(np.float32), (0, 0), 1.0)
        out = mix(out, right, mr); out = mix(out, left, ml)
        # soft shadow cast on the grey slat
        for ub, side in ((u1, 1), (u2, -1)):
            d = (u - ub) * side                              # >0 inside coloured slat
            sh = np.clip(1 - np.abs(np.minimum(d, 0)) / 22.0, 0, 1) * (d < 0) * 0.32
            out = (out.astype(np.float32) * (1 - sh[..., None])).astype(np.uint8)
    if f >= 96:
        if c.state.get("pm_i", -99) < c.i - 6:
            c.state["pm"] = person_mask(warp(img, tx=-0.157 * W, ty=0.162 * H)); c.state["pm_i"] = c.i
        m = c.state["pm"]
        a = ease((f - 96) / 14.0)
        out = mix(out, np.full_like(out, 255), m * a)
        out = flash(out, ease((f - 111) / 6.0))
        if f >= 118:
            out = mix(np.full_like(out, 255), img, ease((f - 118) / 9.0))
    return out

# ----------------------------------------------------------------------------- 15. срез вверх фликер
_SU_B = [(0, 1), (12, 1), (13, .8), (26, .8), (27, .5), (32, .5), (33, .6), (59, .6), (60, .4), (71, .4), (72, .3), (83, .3), (84, .16), (88, .08), (91, 0)]
_SU_EV = [(15, 19, "w", .80, .95), (20, 23, "g", .52, .72), (24, 32, "w", .50, .95), (35, 48, "w", .60, .82),
          (60, 66, "g", .52, .64), (69, 84, "w", .43, .70), (85, 93, "w", .55, .66)]
def fx_sliceup(img, t, c):
    W, H, sc = c.W, c.H, c.sc
    f = t * 30.0
    if f >= 94: return img
    b = kf(f, _SU_B)
    zoomed = cv2.resize(img[int(.25 * H):int(.75 * H), int(.25 * W):int(.75 * W)], (W, H), interpolation=cv2.INTER_LINEAR)
    yb = int(b * H)
    out = img.copy()
    out[:yb] = zoomed[:yb]
    for (a, e, kind, y0f, y1f) in _SU_EV:
        if not (a <= f < e): continue
        y0, y1 = int(y0f * H), int(y1f * H)
        seg = out[y0:y1]
        if kind == "w":                                  # blown-out, mirrored, soft block
            seg = cv2.GaussianBlur(seg[:, ::-1], (0, 0), 5 * sc)
            seg = np.clip(seg.astype(np.float32) * 1.15 + 120, 0, 255).astype(np.uint8)
        else:                                            # dark smeared block
            seg = box_blur_h(cv2.GaussianBlur(seg, (0, 0), 8 * sc), int(120 * sc))
            seg = (seg.astype(np.float32) * 0.45 + 12).astype(np.uint8)
        out[y0:y1] = seg
    return out

# ----------------------------------------------------------------------------- 16. цвето качели
_CS_PURPLE = np.array([[0.653, -0.038, 0.125, 56.97], [-0.206, 0.922, 0.061, 32.0], [-0.198, 0.185, 1.027, 55.75]], np.float32)
_CS_TEAL = np.array([[0.675, 0.017, -0.022, -1.55], [0.004, 1.036, -0.043, -0.15], [-0.013, 0.058, 0.953, -0.21]], np.float32)
# "дубль кадра": at the purple peaks the reference mixes in a frame from another moment (found by matching every reference frame
# to the source: it jumps -3, +4, -6, +14, -14 source frames around t = 1..5 s). (t0, t1, dt0, dt1, alpha0, alpha1), seconds
_CS_ECHO = [(0.933, 1.167, -0.21, -0.21, 0.4, 0.6), (1.967, 2.1, 0.33, 0.33, 0.1, 0.4), (2.9, 3.2, -0.08, -0.42, 0.3, 0.6),
            (3.8, 4.13, 0.67, 0.42, 0.5, 0.1), (4.87, 5.1, -0.42, -0.42, 0.3, 0.5)]
def fx_colorswing(img, t, c):
    tt = t % 6.0
    for (t0, t1, d0, d1, a0, a1) in _CS_ECHO:
        if t0 <= tt <= t1:
            u = (tt - t0) / (t1 - t0)
            img = mix(img, c.neighbor(d0 + (d1 - d0) * u), a0 + (a1 - a0) * u)
            break
    img = cam(img, "colorswing", t, c)     # sway measured on the reference
    u = tri(t / 1.0)                      # 0 purple -> 1 teal -> 0 purple, period 1 s
    M = _CS_PURPLE * (1 - u) + _CS_TEAL * u
    return grade(img, M)


# ----------------------------------------------------------------------------- 17. formulas
# Chalk-style maths and a few triangles float on the background BEHIND the person. Drawn procedurally (original artwork, no bundled matte):
# every item fades in, hangs, fades out on its own cycle, so the effect loops for as long as it is switched on.
_FORMULAS = ["E = mc²", "a² + b² = c²", "∫ f(x) dx", "A = πr²", "F = ma", "V = IR", "sin²θ + cos²θ = 1", "x = (−b ± √(b² − 4ac)) / 2a",
             "e^(iπ) + 1 = 0", "Σ 1/n² = π²/6", "λ = h / p", "v = s / t", "P = F / A", "Δx · Δp ≥ ħ/2", "c² = a² + b²", "∞ ≠ 0", "√2 ≈ 1.414", "π ≈ 3.14159"]

def _chalk_font(size):
    p = _asset("Inter-Bold.otf")
    from PIL import ImageFont
    try: return ImageFont.truetype(p, int(max(8, size))) if p else ImageFont.load_default()
    except Exception: return ImageFont.load_default()

def _chalk_patch(txt, size, angle, rng):
    """float32 alpha patch of chalk text (grainy edges), rotated; None if the font lacks a glyph"""
    from PIL import Image, ImageDraw
    f = _chalk_font(size)
    try:
        l, t_, r, b = f.getbbox(txt)
    except Exception: return None
    w, h = int(r - l + 24), int(b - t_ + 24)
    im = Image.new("L", (w, h), 0); ImageDraw.Draw(im).text((12 - l, 12 - t_), txt, font=f, fill=255)
    a = np.asarray(im, np.float32) / 255.0
    grain = cv2.GaussianBlur(rng.random(a.shape).astype(np.float32), (0, 0), 0.8)
    a = np.clip(a * (0.62 + 0.9 * (grain - 0.5) + 0.38), 0, 1)                     # chalk: random thin spots inside the strokes
    M = cv2.getRotationMatrix2D((w / 2.0, h / 2.0), angle, 1.0)
    cs, sn = abs(M[0, 0]), abs(M[0, 1]); nw, nh = int(h * sn + w * cs) + 2, int(h * cs + w * sn) + 2
    M[0, 2] += nw / 2.0 - w / 2.0; M[1, 2] += nh / 2.0 - h / 2.0
    return cv2.warpAffine(a, M, (nw, nh), flags=cv2.INTER_LINEAR)

def _triangle_patch(size, angle, rng):
    n = int(size * 1.5); im = np.zeros((n, n), np.float32)
    pts = np.array([[0.12 * n, 0.82 * n], [0.88 * n, 0.82 * n], [0.12 * n, 0.18 * n]], np.int32)
    cv2.polylines(im, [pts], True, 1.0, max(2, int(size * 0.045)), cv2.LINE_AA)
    s_ = int(0.12 * n); cv2.rectangle(im, (int(0.12 * n), int(0.82 * n) - s_), (int(0.12 * n) + s_, int(0.82 * n)), 1.0, max(1, int(size * 0.03)), cv2.LINE_AA)
    grain = cv2.GaussianBlur(rng.random(im.shape).astype(np.float32), (0, 0), 0.8); im = np.clip(im * (0.62 + 0.9 * (grain - 0.5) + 0.38), 0, 1)
    M = cv2.getRotationMatrix2D((n / 2.0, n / 2.0), angle, 1.0)
    return cv2.warpAffine(im, M, (n, n), flags=cv2.INTER_LINEAR)

def _formula_items(W, H, seed):
    """26 items (formulas + triangles) at random places that never overlap and stay fully inside the frame"""
    rng = np.random.default_rng(seed + 17)
    names = list(_FORMULAS); rng.shuffle(names)
    items, boxes = [], []; pad = 0.012 * W; mx = 0.03 * W
    for k in range(26):
        ang = rng.uniform(-12, 12)
        if k % 6 == 2: p = _triangle_patch(W * rng.uniform(0.11, 0.15), ang, rng)
        else:
            p = None
            for _ in range(4):
                if not names: names = list(_FORMULAS); rng.shuffle(names)
                p = _chalk_patch(names.pop(), W * rng.uniform(0.046, 0.068), ang, rng)
                if p is not None and p.shape[1] <= W - 2 * mx: break
                p = None
        if p is None: continue
        ph, pw = p.shape
        for _try in range(80):
            cx = rng.uniform(mx + pw / 2.0, W - mx - pw / 2.0); cy = rng.uniform(0.03 * H + ph / 2.0, 0.97 * H - ph / 2.0)
            bx = (cx - pw / 2.0 - pad, cy - ph / 2.0 - pad, cx + pw / 2.0 + pad, cy + ph / 2.0 + pad)
            if all(bx[2] < o[0] or bx[0] > o[2] or bx[3] < o[1] or bx[1] > o[3] for o in boxes):
                boxes.append(bx); items.append(dict(p=p, cx=cx, cy=cy, period=rng.uniform(3.0, 4.4), off=rng.uniform(0, 4.4), fl=rng.uniform(0, 6.28))); break
    return items

def fx_formulas(img, t, c):
    W, H = c.W, c.H
    items = c.state.get("formulas")
    if items is None: items = c.state["formulas"] = _formula_items(W, H, int(getattr(c, "seed", 7)))
    A = np.zeros((H, W), np.float32)
    for it in items:
        p_ = ((t + it["off"]) % it["period"]) / it["period"]
        e = ease(p_ / 0.16) * (1.0 - ease((p_ - 0.80) / 0.16))
        if e <= 0.01 or it["p"] is None: continue
        ph, pw = it["p"].shape
        x0 = int(round(it["cx"] - pw / 2.0 + 0.006 * W * np.sin(0.9 * t + it["fl"]))); y0 = int(round(it["cy"] - ph / 2.0 + 0.004 * H * np.sin(0.7 * t + it["fl"] * 1.7) - (1 - e) * 0.01 * H))
        X0, Y0, X1, Y1 = max(0, x0), max(0, y0), min(W, x0 + pw), min(H, y0 + ph)
        if X1 <= X0 or Y1 <= Y0: continue
        A[Y0:Y1, X0:X1] = np.maximum(A[Y0:Y1, X0:X1], it["p"][Y0 - y0:Y1 - y0, X0 - x0:X1 - x0] * e)
    # formulas live BEHIND the person: neural matte (bundled u2netp); on a plain background without the model the colour difference is used
    pm = None
    if not c.no_matte:
        try:
            import scenes as S_
            pm = S_.matte(img, c)
        except Exception: pm = None
        if pm is None:
            if c.state.get("flat") is None:
                edge = np.concatenate([img[:H // 12].reshape(-1, 3), img[-H // 12:].reshape(-1, 3)]).astype(np.float32)
                c.state["flat"] = bool(edge.std(axis=0).mean() < 14)
            if c.state["flat"]:
                if c.i % 6 == 0 or "pm17" not in c.state: c.state["pm17"] = person_mask(img)
                pm = c.state["pm17"]
    if pm is not None: A = A * (1 - np.clip(pm * 1.15, 0, 1))
    return mix(img, np.full_like(img, 255), A * 0.92)

# ----------------------------------------------------------------------------- 18. радужное свечение
def fx_rainbow(img, t, c):
    W, H, sc = c.W, c.H, c.sc
    g = c.state.get("rb_glow")
    if g is None:
        yy, xx = np.mgrid[0:H, 0:W].astype(np.float32)
        dh = np.minimum(xx, W - 1 - xx); dv = np.minimum(yy, H - 1 - yy)
        ch = 0.97 * np.exp(-dh / (0.0444 * W)); cv_ = 0.97 * np.exp(-dv / (0.048 * H))   # decay lengths measured on the reference
        g = 1 - (1 - ch) * (1 - cv_)                               # glow strength, strongest at the edges
        c.state["rb_glow"] = g.astype(np.float32)
        c.state["rb_phase"] = (360.0 * (xx / W - yy / H)).astype(np.float32)
    hue = (236.0 + 288.0 * t + c.state["rb_phase"]) % 360.0            # diagonal rainbow that rotates 288 deg/s
    hsv = np.stack([hue / 2.0, np.full_like(hue, 235.0), np.full_like(hue, 255.0)], axis=-1).astype(np.uint8)
    col = cv2.cvtColor(hsv, cv2.COLOR_HSV2BGR).astype(np.float32) / 255.0
    cc = col * c.state["rb_glow"][..., None]
    out = 255.0 - (255.0 - img.astype(np.float32)) * (1.0 - cc)        # "screen" blend, measured on the reference
    return np.clip(out, 0, 255).astype(np.uint8)


# ----------------------------------------------------------------------------- 19. grid-dive (стена из кадров)
# From the screencast: the picture pulls back into a tilted wall of tiles, every tile is another moment of the clip, then dives back in.
_GD_S = [(0.0, 1.0), (0.033, 0.96), (0.15, 0.20), (0.27, 0.19), (0.62, 0.20), (0.70, 0.5), (0.80, 1.0)]    # tile scale vs time (s)
def fx_griddive(img, t, c):
    W, H, sc = c.W, c.H, c.sc
    S = kf(t, _GD_S)
    if S >= 0.999 or t > 0.85: return img
    ang = -3.0 * (1 - S) / 0.8
    pitch = 1.18
    tw_, th_ = max(2, int(S * W)), max(2, int(S * H))
    bg = np.empty_like(img); bg[:] = (250, 247, 243)
    canvas = bg.copy()
    px, py = pitch * S * W, pitch * S * H
    ni = int(np.ceil(W * 0.9 / px)) + 1; nj = int(np.ceil(H * 0.9 / py)) + 1
    cols = 2 * ni + 1
    gap = max(2, int(0.012 * W * min(1.0, S * 3)))
    for j in range(-nj, nj + 1):
        for i in range(-ni, ni + 1):
            cx = W / 2 + i * px; cy = H / 2 + j * py
            x0 = int(round(cx - tw_ / 2)); y0 = int(round(cy - th_ / 2))
            if x0 + tw_ < -W * 0.2 or x0 > W * 1.2 or y0 + th_ < -H * 0.2 or y0 > H * 1.2: continue
            if i == 0 and j == 0: tile = resize(img, tw_, th_)
            else:
                n = j * cols + i
                tile = resize(c.thumb(n * 0.07), tw_, th_)
            # plate (light frame) around each tile
            xa, ya, xb, yb = x0 - gap, y0 - gap, x0 + tw_ + gap, y0 + th_ + gap
            cxa, cya, cxb, cyb = max(0, xa), max(0, ya), min(W, xb), min(H, yb)
            if cxb > cxa and cyb > cya: canvas[cya:cyb, cxa:cxb] = (232, 230, 228)
            sx0, sy0, sx1, sy1 = max(0, x0), max(0, y0), min(W, x0 + tw_), min(H, y0 + th_)
            if sx1 > sx0 and sy1 > sy0: canvas[sy0:sy1, sx0:sx1] = tile[sy0 - y0:sy1 - y0, sx0 - x0:sx1 - x0]
    if abs(ang) > 0.01:
        canvas = warp(canvas, rot=ang, border=cv2.BORDER_REPLICATE)
    return canvas

# ----------------------------------------------------------------------------- 20. screen-in-screen (Frame Break)
# From the screencast: the portrait picture squeezes into a wide "monitor" card on a white desk, stays there ~0.9 s, then expands back.
def fx_screeninscreen(img, t, c):
    W, H, sc = c.W, c.H, c.sc
    if t > 1.5: return img
    k = kf(t, [(0.0, 0.0), (0.2, 0.0), (0.4, 1.0), (1.27, 1.0), (1.47, 0.0)])
    if k <= 0.0: return img
    e = ease(k)
    # find the face once and build a wide window around it: hair-to-chin must fit completely
    if "sis_src" not in c.state:
        fb = None
        if c.fixed_face is not None:
            fb = np.array([c.fixed_face[0] * W, c.fixed_face[1] * H, c.fixed_face[2] * W, c.fixed_face[3] * H], np.float32)
        else:
            fb = detect_face(img)
        if fb is None: fb = np.array([W * .327, H * .255, W * .352, H * .198], np.float32)
        fx_, fy_, fw_, fh_ = fb
        cy = fy_ + fh_ * 0.40                                   # hair top .. chin centre
        hh = fh_ * 1.80                                         # window height around the face
        cw_ = W
        hh = min(max(hh, W / 3.2), H * 0.5)
        cx_ = W / 2.0
        y0 = float(np.clip(cy - hh / 2, 0, H - hh))
        c.state["sis_src"] = np.array([0.0, y0 / H, 1.0, (y0 + hh) / H])
    s1 = c.state["sis_src"]; s0 = np.array([0, 0, 1, 1.0])
    ratio = (s1[2] * W) / max(1.0, (s1[3] - s1[1]) * H)          # window aspect
    dw = 0.988; dh = dw * W / ratio / H
    dtop = 0.127
    d0 = np.array([0, 0, 1, 1.0]); d1 = np.array([(1 - dw) / 2, dtop, (1 + dw) / 2, dtop + dh])
    sr = s0 + (s1 - s0) * e; dr = d0 + (d1 - d0) * e
    out = np.empty_like(img)
    ys = np.linspace(255, 236, H).astype(np.float32)[:, None, None]
    out[:] = np.clip(np.broadcast_to(ys, (H, W, 3)), 0, 255).astype(np.uint8)
    sx0, sy0, sx1, sy1 = int(sr[0] * W), int(sr[1] * H), int(sr[2] * W), int(sr[3] * H)
    dx0, dy0, dx1, dy1 = int(dr[0] * W), int(dr[1] * H), int(dr[2] * W), int(dr[3] * H)
    sh = np.zeros((H, W), np.float32); sh[dy1:dy1 + int(0.012 * H), dx0 + 8:dx1 - 8] = 0.35
    sh = cv2.GaussianBlur(sh, (0, 0), 0.01 * H)
    out = (out.astype(np.float32) * (1 - 0.55 * sh[..., None])).astype(np.uint8)
    card = cv2.resize(img[sy0:sy1, sx0:sx1], (max(2, dx1 - dx0), max(2, dy1 - dy0)), interpolation=cv2.INTER_AREA)
    out[dy0:dy0 + card.shape[0], dx0:dx0 + card.shape[1]] = card
    bw = max(1, int(round(3 * sc * e)))
    cv2.rectangle(out, (dx0, dy0), (dx1 - 1, dy1 - 1), (40, 38, 36), bw)
    return out

