# single numbered list of all effects (01-16 edit presets, 17-20 formulas / rainbow / grid-dive / screen-in-screen, 21-30 scenes, 31-42 more scenes and looks, 43-47 varieties of older scenes)
NUMBERED = ["sparkle", "vglitch", "dropin", "details", "clasp", "pulse", "mosaic", "soft", "slicemerge", "strip", "cursed", "split", "heartbeat", "mix", "sliceup", "colorswing",
            "formulas", "rainbow", "griddive", "screeninscreen",
            "orbit", "chat", "snapzoom", "checklistpop", "headlinestorm", "papercutout", "liquidglass", "greenscreen", "digitalzoom", "phonemock",
            "quickzoom", "smoothzoomout", "colorframe", "framebreak", "growthchart", "pipdelay", "splitscreen", "magazine", "bwframe", "pixelate", "vignette", "fadeblack",
            "iconsaround", "greenbg", "checklist2", "headlinestorm2", "phonemock2"]

def number_of(key):
    return NUMBERED.index(key) + 1 if key in NUMBERED else 0

def resolve(name):
    n = name.strip().lower().replace("ё", "е")
    m = n.lstrip("№#").strip()
    if m.isdigit():                                     # --effect 23  /  --effect №23
        k = int(m)
        if 1 <= k <= len(NUMBERED) and NUMBERED[k - 1] in EFFECTS: return NUMBERED[k - 1]
        raise SystemExit("No effect number %s. Use --list." % m)
    for k, v in EFFECTS.items():
        names = [k, v["ru"]] + v["alias"]
        if n in [x.lower().replace("ё", "е") for x in names]:
            return k
    for k, v in EFFECTS.items():
        if n in v["ru"].lower().replace("ё", "е") or any(n in a.lower().replace("ё", "е") for a in v["alias"]):
            return k
    raise SystemExit("Unknown effect %r. Use --list." % name)

# ----------------------------------------------------------------------------- video io
def probe(path):
    out = subprocess.check_output(["ffprobe", "-v", "error", "-select_streams", "v:0", "-show_streams", "-of", "json", path])
    s = json.loads(out)["streams"][0]
    W, H = int(s["width"]), int(s["height"])
    rot = 0
    for sd in s.get("side_data_list", []) or []:
        if "rotation" in sd: rot = int(float(sd["rotation"]))
    rot = rot or int(s.get("tags", {}).get("rotate", 0) or 0)
    if abs(rot) % 180 == 90: W, H = H, W
    a = s.get("avg_frame_rate", "0/1")
    n, d = a.split("/")
    fps = float(n) / float(d) if float(d) else 0
    if not fps or fps > 120:
        n, d = s["r_frame_rate"].split("/"); fps = float(n) / float(d)
    has_audio = bool(subprocess.run(["ffprobe", "-v", "error", "-select_streams", "a", "-show_entries", "stream=index", "-of", "csv=p=0", path],
                                    capture_output=True, text=True).stdout.strip())
    return W, H, fps, has_audio

# recommended --duration range as a factor of the native length (outside it the effect gets jerky or drags); everything else: 0.7x - 2x
DUR_FACTORS = {"quickzoom": (0.85, 2.0), "smoothzoomout": (0.8, 2.0), "pixelate": (0.8, 2.0), "bwframe": (0.8, 2.0), "fadeblack": (0.8, 2.0),
               "vignette": (0.8, 2.0), "dropin": (0.8, 2.0), "griddive": (0.8, 2.0), "colorframe": (0.8, 2.0), "framebreak": (0.8, 2.0)}

def dur_range(key):
    d = EFFECTS[key].get("dur")
    if EFFECTS[key].get("kind") != "intro" or not d: return None
    lo, hi = DUR_FACTORS.get(key, (0.7, 2.0)); return round(d * lo, 2), round(d * hi, 2)

def check_duration(key, duration, quiet=False):
    """None if --duration is not given or does not apply; otherwise the length in seconds (a warning if outside the recommended range)"""
    if duration is None: return None
    r = dur_range(key)
    if r is None:
        print("--duration ignored: '%s' is a continuous effect (it runs from --start to --end), only intro effects have a length" % key, file=sys.stderr); return None
    if duration <= 0.05: raise SystemExit("--duration must be larger than 0.05 s")
    if not quiet and not (r[0] - 1e-6 <= duration <= r[1] + 1e-6):
        print("--duration %.2f s is outside the recommended range %.2f-%.2f s for '%s': the effect may look jerky or sluggish (applied as given)" % (duration, r[0], r[1], key), file=sys.stderr)
    return float(duration)

def render(inp, outp, effect, start=0.0, end=None, seed=7, max_seconds=None, crf=17, quiet=False, face=None, scale_w=None, opts=None, repeat=None, duration=None):
    """one effect: a thin wrapper around render_stack()"""
    return render_stack(inp, outp, [dict(effect=effect, start=start, end=end, seed=seed, face=face, opts=opts, repeat=repeat, duration=duration)],
                        max_seconds=max_seconds, crf=crf, quiet=quiet)

def render_stack(inp, outp, layers, max_seconds=None, crf=17, quiet=False):
    """several effects in ONE pass: every frame goes through the layers in list order (the output of one layer is the input of the next).
    layer = dict(effect, start, end, duration, repeat, seed, face, opts). Effects that look at other moments of the clip
    (delayed picture-in-picture, wall of frames, colour swing) see the ORIGINAL frames, not the output of earlier layers."""
    W, H, fps, has_audio = probe(inp)
    W2, H2 = W - W % 2, H - H % 2
    L = []
    for ly in layers:
        key = resolve(ly["effect"]); spec = EFFECTS[key]
        c = Ctx(W, H, fps, ly.get("seed", 7)); c.fixed_face = ly.get("face"); c.opts = ly.get("opts") or {}
        L.append(dict(key=key, spec=spec, ctx=c, start=float(ly.get("start") or 0.0), end=ly.get("end"), repeat=ly.get("repeat"),
                      duration=check_duration(key, ly.get("duration"), quiet)))
    cmd_in = ["ffmpeg", "-v", "error", "-i", inp, "-an", "-vf", "fps=%s" % fps, "-f", "rawvideo", "-pix_fmt", "bgr24", "-"]
    if max_seconds: cmd_in[3:3] = ["-t", str(max_seconds)]
    reader = subprocess.Popen(cmd_in, stdout=subprocess.PIPE)
    cmd_out = ["ffmpeg", "-v", "error", "-y", "-f", "rawvideo", "-pix_fmt", "bgr24", "-s", "%dx%d" % (W, H), "-r", "%s" % fps, "-i", "-"]
    if has_audio:
        if max_seconds: cmd_out += ["-t", str(max_seconds)]
        cmd_out += ["-i", inp]
    cmd_out += ["-map", "0:v"] + (["-map", "1:a:0", "-c:a", "aac", "-b:a", "192k"] if has_audio else [])
    cmd_out += ["-vf", "crop=%d:%d:0:0" % (W2, H2), "-c:v", "libx264", "-preset", "veryfast", "-crf", str(crf), "-pix_fmt", "yuv420p",
                "-movflags", "+faststart", "-shortest", outp]
    writer = subprocess.Popen(cmd_out, stdin=subprocess.PIPE)
    fsz = W * H * 3
    ahead = max(int(l["spec"].get("ahead", 0) * fps) + 1 for l in L); back = max(int(l["spec"].get("back", 0) * fps) + 1 for l in L)
    tws = sorted(set(int(l["spec"].get("thumb_w", 0)) for l in L if l["spec"].get("thumb_w")))
    tahead = max([int(l["spec"].get("thumb_span", 0) * fps) for l in L if l["spec"].get("thumb_w")] or [0])
    if tws: ahead = max(ahead, tahead)
    buf = {}; thumbs = dict((tw, {}) for tw in tws); nread = [0]
    for l in L:
        l["ctx"].buf = buf; l["ctx"].thumbs = thumbs.get(int(l["spec"].get("thumb_w", 0)), {})
    eof = False
    def fill(upto):
        nonlocal eof
        while not eof and nread[0] <= upto:
            raw = reader.stdout.read(fsz)
            if len(raw) < fsz: eof = True; break
            fr_ = np.frombuffer(raw, np.uint8).reshape(H, W, 3).copy()
            buf[nread[0]] = fr_
            for tw in tws: thumbs[tw][nread[0]] = cv2.resize(fr_, (tw, max(1, int(H * tw / W))), interpolation=cv2.INTER_AREA)
            nread[0] += 1
    i = 0
    while True:
        fill(i + ahead)
        if i >= nread[0]: break
        res = buf[i]
        for old in [k for k in buf if k < i - back]: del buf[old]
        for tw in tws:
            for old in [k for k in thumbs[tw] if k < i - tahead]: del thumbs[tw][old]
        t = i / fps
        for l in L:
            ctx, spec = l["ctx"], l["spec"]
            ctx.n_read = nread[0]; ctx.i_abs = i; ctx.i = i
            if t >= l["start"] and (l["end"] is None or t < l["end"]):
                ctx.i = i - int(round(l["start"] * fps))
                tt = t - l["start"]
                if spec.get("kind") == "intro" and spec.get("dur"):
                    dd = l["duration"] or spec["dur"]                   # --duration: the whole effect is stretched / squeezed in time
                    if l["repeat"] is not None: tt = tt % (dd + l["repeat"])   # demo mode: replay the intro effect again and again
                    tt = tt * spec["dur"] / dd
                res = spec["fn"](res.copy(), tt, ctx)
        writer.stdin.write(np.ascontiguousarray(res, dtype=np.uint8).tobytes())
        i += 1
        if not quiet and i % 60 == 0: print("  frame", i, file=sys.stderr)
    writer.stdin.close(); writer.wait(); reader.wait()
    if writer.returncode != 0: raise SystemExit("ffmpeg failed")
    return i

def _opts(a):
    o = {'text': a.text, 'items': a.items, 'style': a.style, 'lang': a.lang}
    for kv in a.opt:
        if "=" in kv:
            k, v = kv.split("=", 1); o[k.strip().lower()] = v.strip()
    return o

PRESET_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "presets")

def _read_json(path):
    try:
        with open(path, encoding="utf-8") as f: return json.load(f)
    except (OSError, ValueError) as e:
        raise SystemExit("Cannot read %s: %s" % (path, e))

def _load_layers(a):
    """--plan FILE.json or --preset NAME  ->  list of layers for render_stack(); None if neither is given.
    Plan file: {"effects": [{"effect": "quickzoom", "start": 0.5, "duration": 1.5, "text": "...", "items": "a|b", "opt": {"key": "value"},
    "style": "...", "lang": "en", "seed": 7, "face": "x,y,w,h", "end": 4, "repeat": 0.5}, ...]}. The global --text/--items/--opt/--style/--lang/--seed
    are the defaults of every layer; a layer's own keys override them."""
    if not a.plan and not a.preset: return None
    if a.plan and a.preset: raise SystemExit("Use either --plan or --preset, not both")
    if a.preset:
        path = os.path.join(PRESET_DIR, a.preset + ".json")
        if not os.path.isfile(path): raise SystemExit("Preset '%s' not found. Available: %s" % (a.preset, ", ".join(_preset_names()) or "none"))
    else:
        path = a.plan
        if not os.path.isfile(path): raise SystemExit("Plan file not found: %s" % path)
    data = _read_json(path)
    items = data.get("effects") if isinstance(data, dict) else data
    if not isinstance(items, list) or not items: raise SystemExit("%s: need a non-empty list under \"effects\"" % path)
    glob = _opts(a); layers = []
    for n, e in enumerate(items, 1):
        if not isinstance(e, dict) or "effect" not in e: raise SystemExit("%s: entry %d has no \"effect\"" % (path, n))
        o = dict(glob)
        for k in ("text", "style", "lang"):
            if e.get(k) is not None: o[k] = str(e[k])
        if e.get("items") is not None: o["items"] = "|".join(map(str, e["items"])) if isinstance(e["items"], list) else str(e["items"])
        for k, v in (e.get("opt") or {}).items(): o[str(k).strip().lower()] = str(v)
        face = e.get("face")
        if isinstance(face, str): face = tuple(float(v) for v in face.split(","))
        layers.append(dict(effect=e["effect"], start=e.get("start", 0.0), end=e.get("end"), duration=e.get("duration"), repeat=e.get("repeat"),
                           seed=e.get("seed", a.seed), face=face, opts=o))
    return layers

def _preset_names():
    try: return sorted(f[:-5] for f in os.listdir(PRESET_DIR) if f.endswith(".json"))
    except OSError: return []

def _list_presets():
    for n in _preset_names():
        d = _read_json(os.path.join(PRESET_DIR, n + ".json"))
        steps = ", ".join("%s@%gs" % (e["effect"], e.get("start", 0)) + (("-%gs" % e["end"]) if e.get("end") else "") for e in d.get("effects", []))
        print("%-12s | %s | %s" % (n, d.get("description", ""), steps))

def _list(lang):
    for k in NUMBERED:
        v = EFFECTS[k]
        desc = v["desc"] if lang == "ru" else DESC_EN.get(k, v["desc"])
        r = dur_range(k)
        extra = (" [length %.2f s, --duration range %.2f-%.2f s]" % (v["dur"], r[0], r[1])) if r else " [continuous: --start .. --end]"
        print("%02d | %-14s | %-34s | %s%s" % (number_of(k), k, v["ru"], desc, extra))

def main():
    try: sys.stdout.reconfigure(encoding="utf-8", errors="replace"); sys.stderr.reconfigure(encoding="utf-8", errors="replace")
    except Exception: pass
    ap = argparse.ArgumentParser(description="47 video effects (edit presets and scene effects). Start with --check and --list.")
    ap.add_argument("input", nargs="?", help="input video"); ap.add_argument("output", nargs="?", help="output .mp4 (a folder with --effect all)")
    ap.add_argument("--effect", "-e", help="effect id, English alias, Russian name, number from --list, or 'all'"); ap.add_argument("--list", action="store_true", help="list all effects")
    ap.add_argument("--check", action="store_true", help="check Python packages, ffmpeg and bundled models, then exit")
    ap.add_argument("--start", type=float, default=0.0, help="seconds: when the effect begins")
    ap.add_argument("--end", type=float, default=None, help="seconds: when the effect stops (continuous effects only)")
    ap.add_argument("--duration", type=float, default=None, metavar="SEC", help="length of an intro effect in seconds (the whole effect is stretched or squeezed proportionally); the recommended range is shown by --list; continuous effects ignore it")
    ap.add_argument("--repeat", type=float, default=None, metavar="PAUSE", help="demo mode: an intro effect plays again and again with PAUSE seconds between plays (e.g. --repeat 0.5); by default it plays once")
    ap.add_argument("--face", default=None, help="mosaic only: face box as fractions x,y,w,h (e.g. 0.33,0.25,0.35,0.2); default = auto-detect")
    ap.add_argument("--text", default=None, help="main text of a scene effect (magazine masthead, chat request, chart or checklist title, caption)")
    ap.add_argument("--items", default=None, help="list for scene effects, separated by ',' (or by '|' when the items contain commas): checklist items, headlines, magazine lines")
    ap.add_argument("--opt", action="append", default=[], metavar="KEY=VALUE", help="any named text/setting of a scene, repeatable: --opt issue=\"ISSUE 7\" --opt barcode=off (keys are listed in SKILL.md)")
    ap.add_argument("--style", default="minimal", help="colours of the scene effects: 'minimal' (default), a file name from styles/ (e.g. example-brand) or a path to your own .json")
    ap.add_argument("--lang", default="en", choices=["en", "ru"], help="language of the default texts drawn by scene effects and of --list descriptions (default: en)")
    ap.add_argument("--plan", default=None, metavar="FILE.json", help="stack several effects in one render: a JSON file with a list of effects, each with its own start/end/duration/texts (see SKILL.md); the order of the list is the order of application")
    ap.add_argument("--preset", default=None, metavar="NAME", help="a ready-made combination of effects from scripts/presets/ (see --list-presets); --text/--items/--opt/--style/--lang apply to all its effects")
    ap.add_argument("--list-presets", action="store_true", help="list the ready-made presets")
    ap.add_argument("--crf", type=int, default=17, help="x264 quality, lower = better (17 default)")
    ap.add_argument("--seed", type=int, default=7, help="another seed = another random pattern (sparkle, glitch, cursed, formulas)")
    ap.add_argument("--preview", type=float, default=None, help="render only the first N seconds (quick check)")
    a = ap.parse_args()
    if a.check:
        import check_env
        raise SystemExit(check_env.main())
    if a.list_presets:
        _list_presets(); return
    if a.list or not (a.effect or a.plan or a.preset):
        _list(a.lang); return
    if not a.input or not a.output: ap.error("INPUT and OUTPUT are required")
    if a.effect and (a.plan or a.preset): raise SystemExit("Use either -e/--effect or --plan/--preset, not both")
    if not os.path.isfile(a.input) and not (a.effect and a.effect.lower() == "all"): raise SystemExit("Input file not found: %s" % a.input)
    if not shutil.which("ffmpeg") or not shutil.which("ffprobe"): raise SystemExit("ffmpeg/ffprobe not found in PATH. Run: python fx.py --check")
    layers = _load_layers(a)
    if layers:
        if a.start or a.end is not None or a.duration is not None or a.repeat is not None or a.face:
            print("note: --start/--end/--duration/--repeat/--face are ignored with --plan/--preset; set them inside the plan", file=sys.stderr)
        n = render_stack(a.input, a.output, layers, max_seconds=a.preview, crf=a.crf)
        print("done: %d frames, %d effects -> %s" % (n, len(layers), a.output)); return
    if a.effect.lower() == "all":
        os.makedirs(a.output, exist_ok=True)
        for k in NUMBERED:
            op = os.path.join(a.output, "%02d-%s.mp4" % (number_of(k), k)); print("->", op, flush=True)
            render(a.input, op, k, a.start, a.end, a.seed, a.preview, crf=a.crf, quiet=True, opts=_opts(a), repeat=a.repeat)   # (--duration is not applied to --effect all)
        return
    face = tuple(float(v) for v in a.face.split(",")) if a.face else None
    n = render(a.input, a.output, a.effect, a.start, a.end, a.seed, a.preview, crf=a.crf, face=face, opts=_opts(a), repeat=a.repeat, duration=a.duration)
    print("done: %d frames -> %s" % (n, a.output))

if __name__ == "__main__":
    main()
